function def = f90_xrobo01_definition
%F90_XROBO01_DEFINITION Task contract for the four-legged running robot.
% The public contract describes physical capabilities and interfaces only.
% Evaluator points and utility thresholds are kept outside this interface.

def = struct;
def.id = "XROBO01";
def.formal_id = "F90-XROBO-01";
def.sim = struct("start", 0.0, "stop", 2.95184041250516, ...
    "max_step", 0.002, "solver", "ode15s");
def.source = struct( ...
    "url", "https://github.com/mathworks/Simscape-Robot-4Legs", ...
    "tag", "25.1.2.7", ...
    "commit", "c983b096b6357e0a54fb1b30ef050eeecedcc19d", ...
    "license", "MathWorks permissive 3-clause, MathWorks-products restriction", ...
    "model", "reference/files/sm_robot_run_4legs.slx");

def.public_inputs = [ ...
    pin("initial_forward_speed_mps", 2.0, 1.75, 2.25, "m/s", ...
        "initial forward speed of the torso"), ...
    pin("supported_mass_kg", 22.5, 19.5, 25.5, "kg", ...
        "mass supported by the four legs at the torso"), ...
    pin("ground_stiffness_npm", 100000, 75000, 130000, "N/m", ...
        "normal penalty stiffness at every foot-ground contact"), ...
    pin("ground_damping_nspm", 250, 175, 350, "N*s/m", ...
        "normal penalty damping at every foot-ground contact"), ...
    pin("propulsive_torque_nm", 0.5, 0.38, 0.65, "N*m", ...
        "stance-phase propulsive hip torque magnitude"), ...
    pin("knee_stiffness_nmprad", 549.764473015946, 430, 680, ...
        "N*m/rad", "common compliant-knee torsional stiffness")];

def.outputs = [ ...
    pout("body_state", 6, "[x,y,z,vx,vy,vz]", ...
        "m and m/s", ...
        "world-referenced torso-frame translation and translational velocity measured by a physical transform sensor"), ...
    pout("contact_state", 4, "[left-front,left-rear,right-front,right-rear]", ...
        "boolean", ...
        "four independent foot-ground contact detections derived from foot penetration and relative velocity"), ...
    pout("gait_state", 3, ...
        "[rear-left/front-right aerial, rear-right/front-left aerial, phase]", ...
        "boolean, boolean, integer", ...
        "contact-driven gait-supervisor outputs"), ...
    pout("electrical_state", 3, ...
        "[bus power, total actuator load current, battery current]", ...
        "W, A, A", ...
        "physical voltage and current sensors on the shared actuator supply")];

def.prompt = strjoin([ ...
    "Build a planar four-legged running robot in Simscape with a finite-mass torso, four articulated two-link legs, compliant knees, physical foot-ground contact, and finite electromechanical hip actuation. A battery-backed electrical supply with an energy-buffering capacitor must feed the actual hip actuators, which transmit torque through mechanical joints to the legs.", ...
    "Read initial_forward_speed_mps, supported_mass_kg, ground_stiffness_npm, ground_damping_nspm, propulsive_torque_nm, and knee_stiffness_nmprad from MATLAB base-workspace variables. Their nominal values are 2.0 m/s, 22.5 kg, 100000 N/m, 250 N*s/m, 0.5 N*m, and 549.764 N*m/rad; their operating ranges are respectively 1.75--2.25, 19.5--25.5, 75000--130000, 175--350, 0.38--0.65, and 430--680 in those units.", ...
    "Assume a clean MATLAB session in which only those declared inputs are provided; every other parameter and initialization dependency must be self-contained. Across the declared range, measured hip angle and angular speed must causally regulate the corresponding physical actuator during aerial motion, foot contact must govern the stance/aerial action, diagonal leg pairs must alternate support, and the torso must continue stable forward locomotion without bypassing the compliant legs or contact forces.", ...
    "Log Timeseries body_state, contact_state, gait_state, and electrical_state. body_state is measured [x,y,z,vx,vy,vz] in the fixed right-handed world frame. contact_state is [left-front,left-rear,right-front,right-rear]. gait_state is [rear-left/front-right aerial,rear-right/front-left aerial,phase]. electrical_state is [shared-bus power,total actuator load current,battery current] measured on the physical supply. Work directly in cand_XROBO01.slx and keep the latest usable state saved there throughout the task."], ...
    sprintf("\n\n"));

def.prompt_zh_review = strjoin([ ...
    "使用 Simscape 构建一个平面四足奔跑机器人，包含有限质量躯干、四条铰接式两连杆腿、柔顺膝关节、真实足地接触以及有限能力的机电髋关节执行机构。带电池和储能电容的电源必须向实际髋关节执行机构供电，执行机构通过机械关节向腿传递转矩。", ...
    "从 MATLAB 基础工作区读取 initial_forward_speed_mps、supported_mass_kg、ground_stiffness_npm、ground_damping_nspm、propulsive_torque_nm 和 knee_stiffness_nmprad。其标称值依次为 2.0 m/s、22.5 kg、100000 N/m、250 N*s/m、0.5 N*m 和 549.764 N*m/rad；工作范围依次为 1.75--2.25、19.5--25.5、75000--130000、175--350、0.38--0.65 和 430--680，单位同上。", ...
    "假设干净 MATLAB 会话中只提供上述公开输入；其他参数和初始化依赖必须自包含。在公开范围内，实测髋关节角度和角速度必须在腾空阶段因果地调节相应物理执行机构，足部接触必须决定支撑/腾空动作，对角腿组必须交替支撑，躯干必须持续稳定向前运动且不得绕过柔顺腿或接触力。", ...
    "记录 Timeseries 变量 body_state、contact_state、gait_state 和 electrical_state。body_state 是固定右手世界坐标系中的实测 [x,y,z,vx,vy,vz]；contact_state 为 [左前、左后、右前、右后]；gait_state 为 [左后/右前腾空、右后/左前腾空、相位]；electrical_state 是物理电源上的 [共享母线功率、执行机构总负载电流、电池电流]。直接在 cand_XROBO01.slx 中工作，并在整个任务过程中持续保存最新可用状态。"], ...
    sprintf("\n\n"));

nominal = nominal_values(def);
def.scenarios = [ ...
    scenario("nominal", "nominal cyclic locomotion", nominal, ...
        "nominal", ""), ...
    scenario("soft_ground_heavy", "soft-ground heavy-mass boundary", ...
        values(1.82, 25.2, 78000, 330, 0.62, 650), ...
        "joint_boundary", ""), ...
    scenario("stiff_ground_fast", "stiff-ground fast boundary", ...
        values(2.22, 20.0, 127000, 190, 0.43, 455), ...
        "joint_boundary", ""), ...
    scenario("low_propulsion_heavy", "low-propulsion heavy-load corner", ...
        values(1.94, 25.3, 106000, 275, 0.39, 570), ...
        "joint_boundary", ""), ...
    scenario("interior_compliance", "interior compliance/contact point", ...
        values(2.10, 23.4, 88000, 225, 0.56, 470), ...
        "fixed_interior", ""), ...
    scenario("torque_pair_low", ...
        "low member of the actuator-causality pair", ...
        values(2.0, 22.5, 100000, 250, 0.40, 549.764473015946), ...
        "paired_probe", "propulsive_torque"), ...
    scenario("torque_pair_high", ...
        "high member of the actuator-causality pair", ...
        values(2.0, 22.5, 100000, 250, 0.63, 549.764473015946), ...
        "paired_probe", "propulsive_torque"), ...
    scenario("ground_stiffness_pair_low", ...
        "low-stiffness member of the contact-causality pair", ...
        values(2.0, 22.5, 80000, 250, 0.5, 549.764473015946), ...
        "paired_probe", "ground_stiffness"), ...
    scenario("ground_stiffness_pair_high", ...
        "high-stiffness member of the contact-causality pair", ...
        values(2.0, 22.5, 125000, 250, 0.5, 549.764473015946), ...
        "paired_probe", "ground_stiffness"), ...
    scenario("ground_damping_pair_low", ...
        "low-damping member of the contact-causality pair", ...
        values(2.0, 22.5, 100000, 185, 0.5, 549.764473015946), ...
        "paired_probe", "ground_damping"), ...
    scenario("ground_damping_pair_high", ...
        "high-damping member of the contact-causality pair", ...
        values(2.0, 22.5, 100000, 330, 0.5, 549.764473015946), ...
        "paired_probe", "ground_damping")];

def.groups = struct( ...
    "G", "physical qualification and complete output contract", ...
    "A", "nominal forward locomotion and support accuracy", ...
    "Q", "nominal body, contact and electrical quality", ...
    "M", "sensor-controller-actuator-contact causal mechanism", ...
    "R", "worst operating-point locomotion quality", ...
    "D", "cyclic gait establishment and repeated landing evidence", ...
    "weights", struct("A", .20, "Q", .15, "M", .25, "R", .25, "D", .15));
end

function v = nominal_values(def)
v = struct;
for k = 1:numel(def.public_inputs)
    v.(def.public_inputs(k).name) = def.public_inputs(k).nominal;
end
end

function v = values(speed, mass, stiffness, damping, torque, knee)
v = struct( ...
    "initial_forward_speed_mps", speed, ...
    "supported_mass_kg", mass, ...
    "ground_stiffness_npm", stiffness, ...
    "ground_damping_nspm", damping, ...
    "propulsive_torque_nm", torque, ...
    "knee_stiffness_nmprad", knee);
end

function s = pin(name, nominal, minv, maxv, unit, meaning)
s = struct("name", name, "nominal", nominal, "min", minv, "max", maxv, ...
    "unit", unit, "meaning", meaning);
end

function s = pout(name, channels, order, unit, source)
s = struct("name", name, "channels", channels, "order", order, ...
    "unit", unit, "physical_source", source);
end

function s = scenario(id, role, vals, kind, pair)
s = struct("id", id, "role", role, "kind", kind, ...
    "pair", pair, "values", vals);
end
